#!/bin/bash

# Определение функции для создания пула процессов
create_pool() {
    local pool_size=$1
    local tasks=("$@")
    local pids=()

    for ((i=0; i<pool_size; i++)); do
        # Запуск задачи в фоновом режиме
        ${tasks[i]} &
        pids+=($!)
    done

    # Ожидание завершения всех задач в пуле
    for pid in "${pids[@]}"; do
        wait $pid
    done
}

# Определение задач
task1() {
    echo "Task 1"
}
task2() {
    echo "Task 2"
}
task3() {
    echo "Task 3"
}
task4() {
    echo "Task 4"
}

# Создание одного пула из четырёх задач
create_pool 4 task1 task2 task3 task4

# Проверка произведения лимитов и дополнительный overhead
echo "Total processes: 4"
echo "Peak processes: 4"
