#!/bin/bash

# Определение функции-обёртки
wrapper() {
    # Запуск GNU Parallel с двумя заданиями
    parallel --jobs 2 ::: "child1" "child2"
}

# Определение функции-потомка
child() {
    # Бесконечный цикл для порождения потомков
    while true; do
        child &
    done
}

# Определение функции-ядро
kernel() {
    # Запуск двух потомков
    child1 &
    child2 &
}

# Определение функции-диспетчера
dispatcher() {
    # Запуск обёртки
    wrapper
}

# Точка входа
dispatcher
