#!/bin/bash

# Определение функции worker
worker() {
    while true; do
        sleep 1
    done
}

# Определение функции pool
pool() {
    for i in {1..2}; do
        worker &
    done
    wait
}

# Определение функции main
main() {
    trap 'killall worker' EXIT
    pool
}

# Запуск основной функции
main
