#!/bin/bash

# Ensure Bash 4.3+
if ((BASH_VERSINFO[0] < 4 || BASH_VERSINFO[1] < 3)); then
    echo "UNSUPPORTED: Bash version must be 4.3+"
    exit 1
fi

# Create a temporary directory
temp_dir=$(mktemp -d)
if [[ $? -ne 0 ]]; then
    echo "Failed to create temporary directory"
    exit 1
fi

# Cleanup function
cleanup() {
    if [[ -d "$temp_dir" ]]; then
        rm -rf "$temp_dir"
    fi
}

# Trap for cleanup on exit
trap cleanup EXIT

# Define the Makefile content
makefile_content=$(cat <<'EOF'
all: target1 target2 target3 target4 target5

target1:
	@echo "Building target1"
	@sleep 1

target2:
	@echo "Building target2"
	@sleep 1

target3:
	@echo "Building target3"
	@sleep 1

target4:
	@echo "Building target4"
	@sleep 1

target5:
	@echo "Building target5"
	@sleep 1
EOF
)

# Write the Makefile to the temporary directory
echo "$makefile_content" > "$temp_dir/Makefile"

# Wrapper function to limit jobs
wrapper() {
    local -n make_jobs=$1
    make -j "$make_jobs" -C "$temp_dir"
}

# Call the wrapper with a limit of 3 jobs
wrapper 3
```

