all: target1 target2 target3 target4 target5

target1:
	@echo "Building target1"
	@sleep 1

target2:
	@echo "Building target2"
	@sleep 1

target3:
	@echo "Building target3"
	@sleep 1

target4:
	@echo "Building target4"
	@sleep 1

target5:
	@echo "Building target5"
	@sleep 1
EOF

# Функция для запуска make с заданным числом jobs
run_make() {
  local jobs=$1
  set -- "$@"
  make -j "$jobs" "$@"
}

# Запуск make с ограничением в 3 jobs
run_make 3 -C "$temp_dir"

# Очистка временного каталога
rm -rf "$temp_dir"
